 import * as CommonModule from "@ethereumjs/common";
 import { Hardfork } from "@ethereumjs/common";
 import type { TxOptions } from "@ethereumjs/tx";
 import { query } from "./query.js";

 type TransactionCommon = NonNullable<TxOptions["common"]>;
 type CommonStatic = {
   custom: (
     chainParamsOrName: { chainId: number | bigint },
     opts?: { hardfork?: string; baseChain?: string | number | bigint }
   ) => unknown;
 };

 const Common =
   (
     CommonModule as unknown as {
       Common?: CommonStatic;
       default?: CommonStatic;
     }
   ).Common ?? (CommonModule as unknown as { default: CommonStatic }).default;

 function parseChainId(chainId: string): number | bigint {
   const parsedChainId = BigInt(chainId);

   if (parsedChainId <= BigInt(Number.MAX_SAFE_INTEGER)) {
     return Number(parsedChainId);
   }

   return parsedChainId;
 }

 export async function getCommon(rpcUrl: string): Promise<TransactionCommon> {
   const chainId = await query<string>(rpcUrl, "eth_chainId", []);

   if (!chainId) {
     throw new Error("getCommon: can't get result of eth_chainId");
   }

   return Common.custom(
     {
       chainId: parseChainId(chainId),
     },
     {
       hardfork: Hardfork.London,
     }
   ) as TransactionCommon;
 }

