tmp=$(mktemp -d) && cd "$tmp" && npm init -y --silent && npm install --silent @ethereumjs/common@3.0.0 @ethereumjs/tx@3.5.0 ethereumjs-util@7.1.4 && node <<'NODE'
const { Common, Hardfork } = require('@ethereumjs/common')
const { TransactionFactory } = require('@ethereumjs/tx')
const { BN } = require('ethereumjs-util')
function withTransactionCompatibility(common) {
  if (typeof common.chainIdBN === 'function' || typeof common.chainId !== 'function') return common
  Object.defineProperty(common, 'chainIdBN', { value: () => new BN(common.chainId().toString()) })
  if (typeof common.copy === 'function') {
    const copy = common.copy.bind(common)
    Object.defineProperty(common, 'copy', { value: () => withTransactionCompatibility(copy()) })
  }
  return common
}
const common = withTransactionCompatibility(Common.custom({ chainId: 1 }, { hardfork: Hardfork.London }))
